        if (len(predictedList) == 0) {
            return (1, 1, 1);
        } else {
            return (0, 0, 0);
        }
    }
    """If we return an empty list recall is zero and precision is one""";
    if (len(predictedList) == 0) {
        return (0, 1, 0);
    }
    """It is guaranteed now that both lists are not empty""";
    precision = 0;
    for entity in predictedList {
