"""
    Constant-width integer serialization
    :param writer:
    :param n:
    :param width:
    :return:
    """
def dump_uint(n: Any) -> object {
    buffer = [];
    while n {
        buffer.append((n & 255));
        n >>= 8;
    }
    return buffer;
}

"""Convert the two pairs of (lower, left), (top, right) in (lat, lon)
    into the four pairs of (lat, lon) of the corners """
def LLTR2domain(lowerleft: Any, topright: Any) -> object {
    (xa, ya) = lowerleft;
    (xb, yb) = topright;
    domain = [(xa, ya), (xa, yb), (xb, yb), (xb, ya)];
    return domain;
}

